insert into public.dictation_clip_answers(clip_id,reference_text) values ('236973c7-4296-5c7e-8a3f-9105e2d14c1e','If those Christians would but lend me their money, instead of building alms houses and hospitals with it, they might burn the Jews'' quarter to morrow, for aught I care.') on conflict (clip_id) do nothing;
