insert into public.dictation_clip_answers(clip_id,reference_text) values ('7bf3db0d-6de9-513e-8b3c-4894a03f8242','In theory it is all very well; but in poor imperfect earthly practice, a governor must be content with doing very much what comes to hand.') on conflict (clip_id) do nothing;
