insert into public.dictation_clip_answers(clip_id,reference_text) values ('675f6272-5bba-52bd-8d0b-ac3999b498b0','I met that prettiest and naughtiest of humanities half-way between here and Thebes, transformed into a perfect Andromache of chaste affection.''') on conflict (clip_id) do nothing;
