insert into public.dictation_clip_answers(clip_id,reference_text) values ('e1752d14-cc0e-515c-84db-0521cd91717b','The fifteen years before the time of this tale had decided the fate of Greece; the last four that of Rome itself.') on conflict (clip_id) do nothing;
