insert into public.dictation_clip_answers(clip_id,reference_text) values ('ff039776-88ea-5fc0-9830-bd5c042b3429','The Egyptian and Syrian Churches, therefore, were destined to labour not for themselves, but for us.') on conflict (clip_id) do nothing;
