insert into public.dictation_clip_answers(clip_id,reference_text) values ('d8466fda-d24d-5763-8d97-a0711a5a4092','So thought many then, and, as I believe, not unwisely.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('2055786e-97e4-5bab-9ad9-4f4f632654a0','quick','libritts:dev-clean:2902_9006_000008_000000','Clip 074 · voice 2902','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 2902 · CC BY 4.0','dictation/clips/quick/3987a307a03959c5a325b00708ce4a3015dea16781b5d9c7eb9be75965aec715.wav','3987a307a03959c5a325b00708ce4a3015dea16781b5d9c7eb9be75965aec715',487244,10150,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('2055786e-97e4-5bab-9ad9-4f4f632654a0','A picture of life in the fifth century must needs contain much which will be painful to any reader, and which the young and innocent will do well to leave altogether unread.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('621d17c2-a0d0-52e6-8403-fe81d5aeca3b','quick','libritts:dev-clean:2902_9006_000020_000002','Clip 075 · voice 2902','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 2902 · CC BY 4.0','dictation/clips/quick/ea11ecfae28ae83f3b87a5100848c79d4f51610d123a88e1aed83177338b99ed.wav','ea11ecfae28ae83f3b87a5100848c79d4f51610d123a88e1aed83177338b99ed',88362,1840,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('621d17c2-a0d0-52e6-8403-fe81d5aeca3b','But now the main body had arrived.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('f5f355d3-76f9-5998-9877-359399cb6974','quick','libritts:dev-clean:2902_9006_000017_000001','Clip 076 · voice 2902','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 2902 · CC BY 4.0','dictation/clips/quick/69ed10f4f0f7809bca70fda2e8d9413283c9a5cd1e1b9f6bff698fa95687ebcf.wav','69ed10f4f0f7809bca70fda2e8d9413283c9a5cd1e1b9f6bff698fa95687ebcf',498766,10390,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('f5f355d3-76f9-5998-9877-359399cb6974','They brought before the minds of churchmen a thousand new questions which must be solved, unless the Church was to relinquish for ever her claims as the great teacher and satisfier of the human soul.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('98017063-3aab-5c83-ac93-000852192b33','quick','libritts:dev-clean:2902_9006_000019_000000','Clip 077 · voice 2902','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 2902 · CC BY 4.0','dictation/clips/quick/6640689d020f1cf42afceb25afab53bdbbe4d62e435617ab9604b38d12a58172.wav','6640689d020f1cf42afceb25afab53bdbbe4d62e435617ab9604b38d12a58172',173804,3620,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('98017063-3aab-5c83-ac93-000852192b33','And the new blood, at the era of this story, was at hand.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('99191729-e85d-5ae7-a59d-7ae54caa4575','quick','libritts:dev-clean:3536_23268_000006_000002','Clip 078 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/ea27477efc11da4ba2156d3c8cd9dba7c7933f52b77f1ca8f06840f53bea691d.wav','ea27477efc11da4ba2156d3c8cd9dba7c7933f52b77f1ca8f06840f53bea691d',75404,1570,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('99191729-e85d-5ae7-a59d-7ae54caa4575','Her guardian looked astonished.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('f837cfb0-d2f1-53d8-bb48-94b33a6c6658','quick','libritts:dev-clean:3536_23268_000019_000000','Clip 079 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/dacf090ba30f369fb3d5e2a795b2bc290e4daa3a0acbb5f65219b74eb88485d6.wav','dacf090ba30f369fb3d5e2a795b2bc290e4daa3a0acbb5f65219b74eb88485d6',134924,2810,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('f837cfb0-d2f1-53d8-bb48-94b33a6c6658','"Miss Milner, you shall not leave the house this evening."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('1c4344da-c7af-5d59-a3df-1d02dad26b3e','quick','libritts:dev-clean:3536_23268_000047_000001','Clip 080 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/8dc13e9aa97f83c6dd5f48399f868561b0c3264c98f2c11052b317b2d4131330.wav','8dc13e9aa97f83c6dd5f48399f868561b0c3264c98f2c11052b317b2d4131330',383084,7980,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('1c4344da-c7af-5d59-a3df-1d02dad26b3e','She was going to reply, but found she could not, without accompanying her words with tears, therefore, after the first attempt, she desisted.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('d5167ad0-9543-5cb0-b000-bba9bb9ab07f','quick','libritts:dev-clean:3536_23268_000021_000000','Clip 081 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/a4b41aaa61cffa41bfe4f7dcb3f3cbaf064cf00452de5988e791b00a962d1b8b.wav','a4b41aaa61cffa41bfe4f7dcb3f3cbaf064cf00452de5988e791b00a962d1b8b',303404,6320,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('d5167ad0-9543-5cb0-b000-bba9bb9ab07f','"I command you to stay at home this evening." And he walked immediately out of the apartment by another door.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('ab42f544-5bfd-54c9-9d95-e0a7a271418f','quick','libritts:dev-clean:3536_23268_000025_000000','Clip 082 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/590a897bf7e306eb30788f42bba0fd9c06dc2f7458853b7c9585bc30c8114ebc.wav','590a897bf7e306eb30788f42bba0fd9c06dc2f7458853b7c9585bc30c8114ebc',241484,5030,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('ab42f544-5bfd-54c9-9d95-e0a7a271418f','"What could be worse, Madam?" cried Miss Milner; "am not I disappointed of the ball?"') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('af4c5255-4018-5032-8803-7bab3d02bf96','quick','libritts:dev-clean:3536_23268_000040_000002','Clip 083 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/d714f4f1986b41e439dd9619d155e0a0a8de3c7788fac09a07e8181e4e363256.wav','d714f4f1986b41e439dd9619d155e0a0a8de3c7788fac09a07e8181e4e363256',263086,5480,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('af4c5255-4018-5032-8803-7bab3d02bf96','Dorriforth read on, and seemed afraid of looking up, lest he should see what he could not have pardoned.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('ff8dc1dd-e2a9-55bc-817c-3c80d338225f','quick','libritts:dev-clean:3536_23268_000006_000000','Clip 084 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/ac971e622bf61efdc0654fd96393c7759acbf1e5287253ef14718cbc646911f6.wav','ac971e622bf61efdc0654fd96393c7759acbf1e5287253ef14718cbc646911f6',392204,8170,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('ff8dc1dd-e2a9-55bc-817c-3c80d338225f','She, however, flattered herself that what she had said might be excused as a mistake, the lapse of memory, or some other trifling fault, when he should know the truth.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('413ea367-62f8-50d3-b5ac-a4fe98eb3983','quick','libritts:dev-clean:3536_23268_000028_000000','Clip 085 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/4a4f3c2e81fbd1ad737515de2079cbaa78efa2f328e3ef9e755dcbdc67c0ba23.wav','4a4f3c2e81fbd1ad737515de2079cbaa78efa2f328e3ef9e755dcbdc67c0ba23',453164,9440,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('413ea367-62f8-50d3-b5ac-a4fe98eb3983','"It is not the first time, I believe, you have acted contrary to that, Miss Milner," replied mrs Horton, and affected a tenderness of voice, to soften the harshness of her words.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('bfd788de-2559-5ffa-8341-a1b9b31bfbb8','quick','libritts:dev-clean:3536_23268_000008_000000','Clip 086 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/14b2ae347ab1d48d82d5783832d891e424cb58b57e0c530b59f483b9a4cec4c2.wav','14b2ae347ab1d48d82d5783832d891e424cb58b57e0c530b59f483b9a4cec4c2',189164,3940,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('bfd788de-2559-5ffa-8341-a1b9b31bfbb8','"I mistook-for I had before given my word that I should pass it abroad."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('b4c53206-787f-5730-b0f5-169756d26baa','quick','libritts:dev-clean:3536_8226_000020_000000','Clip 087 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/aac0b9d3ead98d93fc6522cb7bea2c5e285d29983011450cec9c4488e2f6677c.wav','aac0b9d3ead98d93fc6522cb7bea2c5e285d29983011450cec9c4488e2f6677c',425804,8870,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('b4c53206-787f-5730-b0f5-169756d26baa','"I''m not a taking of her part, b A woman as has a husband as finds her with her wittels regular, and with what''s decent and comfortable beside, ought to be contented.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('d3d74aa7-ea12-5c31-9b7b-af0129028773','quick','libritts:dev-clean:3536_8226_000027_000002','Clip 088 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/49a948a3416e84908f98301affb666f1899276db609b9feda69797282267f0a4.wav','49a948a3416e84908f98301affb666f1899276db609b9feda69797282267f0a4',89322,1860,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('d3d74aa7-ea12-5c31-9b7b-af0129028773','He have been up all this month, sir."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('609028e7-624e-5697-8bfd-d1307c6c622a','quick','libritts:dev-clean:3536_8226_000010_000003','Clip 089 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/49d59271004570f32f167fd688c5dcfee4b042f5fea483ab960245997c755f7a.wav','49d59271004570f32f167fd688c5dcfee4b042f5fea483ab960245997c755f7a',208364,4340,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('609028e7-624e-5697-8bfd-d1307c6c622a','We''d all be shewed up in the papers as that black, that they''d hoot us along the streets.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('22afc390-8fb5-5b36-b47b-dd1727755d3f','quick','libritts:dev-clean:3536_8226_000020_000006','Clip 090 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/2a8714d1ccb3dbb525f40dc5452cb9dc35451356ee1f8c80db4f9a619b03b237.wav','2a8714d1ccb3dbb525f40dc5452cb9dc35451356ee1f8c80db4f9a619b03b237',220844,4600,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('22afc390-8fb5-5b36-b47b-dd1727755d3f','But as for this here child, b--." At that moment there came a knock at the door.') on conflict (clip_id) do nothing;
